using System;
using System.Collections.Generic;
using System.IO;
using Furycube.G9.Protocol;

internal static class ReadHandshakeTests {
    static int assertions;
    static void Check(bool condition,string message){assertions++;if(!condition)throw new Exception(message);}
    static void Throws<T>(Action action,string message) where T:Exception {assertions++;try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name+": "+message);}
    static byte[] Ack(bool ready){return new byte[]{0xA0,ready?(byte)1:(byte)0,0,0,0,0,0,0};}
    sealed class Clock {public long Now;public int Reads;public readonly List<int> Sleeps=new List<int>();public void Wait(int ms){Sleeps.Add(ms);Now+=ms;}public long Time(){return Now;}public byte[] At(int readyAt){Reads++;return Ack(Now>=readyAt);}}
    static void Validation(){Check(!G9ReadHandshake.DecodeReady(Ack(false)),"idle decoded");Check(G9ReadHandshake.DecodeReady(Ack(true)),"ready decoded");G9ReadHandshake.ValidateIdle(Ack(false));Throws<InvalidDataException>(delegate{G9ReadHandshake.ValidateIdle(Ack(true));},"stale response is not drained");Throws<InvalidDataException>(delegate{G9ReadHandshake.DecodeReady(null);},"null response");Throws<InvalidDataException>(delegate{G9ReadHandshake.DecodeReady(new byte[64]);},"padded HID buffer rejected");var unknown=Ack(false);unknown[1]=2;Throws<InvalidDataException>(delegate{G9ReadHandshake.DecodeReady(unknown);},"unknown state");var wrongId=Ack(true);wrongId[0]=0x0A;Throws<InvalidDataException>(delegate{G9ReadHandshake.DecodeReady(wrongId);},"wrong report");for(int i=2;i<8;i++){var bad=Ack(false);bad[i]=1;Throws<InvalidDataException>(delegate{G9ReadHandshake.DecodeReady(bad);},"nonzero padding"+i);}}
    static void DelayedReady(){var clock=new Clock();G9ReadHandshake.WaitForReady(delegate{return clock.At(800);},clock.Wait,clock.Time,2000,100,500);Check(clock.Now==800&&clock.Reads==4,"500ms not ready may become ready at800ms");Check(clock.Sleeps.Count==4&&clock.Sleeps[0]==500,"one initial wait then100ms polls");var immediate=new Clock();G9ReadHandshake.WaitForReady(delegate{return immediate.At(0);},immediate.Wait,immediate.Time);Check(immediate.Now==500&&immediate.Reads==1,"immediate readiness preserves initial transport pacing");var boundary=new Clock();G9ReadHandshake.WaitForReady(delegate{return boundary.At(2000);},boundary.Wait,boundary.Time,2000,100,500);Check(boundary.Now==2000&&boundary.Reads==16,"ready exactly on deadline accepted once");}
    static void Abort(){var never=new Clock();Throws<TimeoutException>(delegate{G9ReadHandshake.WaitForReady(delegate{return never.At(99999);},never.Wait,never.Time,2000,100,500);},"bounded pending");Check(never.Now==2000&&never.Reads==16,"timeout stops at bound without extra GET");var malformed=new Clock();Throws<InvalidDataException>(delegate{G9ReadHandshake.WaitForReady(delegate{malformed.Reads++;var bad=Ack(false);bad[7]=1;return bad;},malformed.Wait,malformed.Time,2000,100,500);},"malformed does not retry");Check(malformed.Reads==1&&malformed.Sleeps.Count==1,"malformed aborts after one read");var transport=new Clock();Throws<IOException>(delegate{G9ReadHandshake.WaitForReady(delegate{transport.Reads++;throw new IOException("synthetic transport failure");},transport.Wait,transport.Time);},"transport failure propagated");Check(transport.Reads==1,"transport error not retried");var late=new Clock();Throws<TimeoutException>(delegate{G9ReadHandshake.WaitForReady(delegate{late.Reads++;late.Now=2001;return Ack(true);},late.Wait,late.Time,2000,100,500);},"late ready from blocking read rejected");Check(late.Reads==1,"late response not repolled");}
    static void Transaction(){var clock=new Clock();int prepares=0,consumes=0;G9ReadHandshake.ValidateIdle(Ack(false));prepares++;G9ReadHandshake.WaitForReady(delegate{return clock.At(700);},clock.Wait,clock.Time,2000,100,500);consumes++;Check(prepares==1&&consumes==1&&clock.Reads==3,"polling changes ACK count, never prepare/payload count");int sent=0;try{G9ReadHandshake.ValidateIdle(Ack(true));sent++;}catch(InvalidDataException){}Check(sent==0,"stale grant prevents initial prepare");int consumed=0;var never=new Clock();try{G9ReadHandshake.WaitForReady(delegate{return never.At(99999);},never.Wait,never.Time,500,100,500);consumed++;}catch(TimeoutException){}Check(consumed==0&&never.Reads==1,"not-ready deadline never authorizes payload read");}
    static void ClockGuards(){int reads=0;Throws<TimeoutException>(delegate{G9ReadHandshake.WaitForReady(delegate{reads++;return Ack(false);},delegate{},delegate{return 0;},2000,100,500);},"frozen clock/wait still bounded");Check(reads==16,"independent wait budget bounds frozen clock");long now=0;Throws<InvalidOperationException>(delegate{G9ReadHandshake.WaitForReady(delegate{return Ack(false);},delegate{now=-1;},delegate{return now;});},"backwards clock");var clock=new Clock();Throws<ArgumentOutOfRangeException>(delegate{G9ReadHandshake.WaitForReady(delegate{return clock.At(0);},clock.Wait,clock.Time,0,100,0);},"zero deadline");Throws<ArgumentOutOfRangeException>(delegate{G9ReadHandshake.WaitForReady(delegate{return clock.At(0);},clock.Wait,clock.Time,2000,0,500);},"zero poll interval");Throws<ArgumentOutOfRangeException>(delegate{G9ReadHandshake.WaitForReady(delegate{return clock.At(0);},clock.Wait,clock.Time,2000,100,2001);},"initial delay outside deadline");Check(clock.Reads==0&&clock.Sleeps.Count==0,"invalid policy has no transport effects");}
    static int Main(){try{Validation();DelayedReady();Abort();Transaction();ClockGuards();Console.WriteLine("ReadHandshakeTests PASS "+assertions);return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
